#!/usr/bin/env python3
"""One-shot exact-preimage integration patch. All inputs validated before writes."""
from pathlib import Path
import base64, hashlib, json, zlib
ROOT=Path(__file__).resolve().parents[2]
PAYLOAD=''''''
changes=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
planned=[]
for name,spec in changes.items():
    path=(ROOT/name).resolve()
    if not path.is_relative_to(ROOT): raise SystemExit('path escape')
    if spec['sha256'] is None:
        if path.exists(): raise SystemExit('new path already exists: '+name)
        text=spec['text']
    else:
        raw=path.read_bytes()
        if hashlib.sha256(raw).hexdigest()!=spec['sha256']: raise SystemExit('source drift: '+name)
        lines=raw.decode().splitlines(keepends=True)
        for start,end,replacement in reversed(spec['edits']):
            if not 0<=start<=end<=len(lines): raise SystemExit('invalid edit: '+name)
            lines[start:end]=[replacement]
        text=''.join(lines)
    planned.append((path,text))
for path,text in planned:
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(text,encoding='utf-8')
    print('wired',path.relative_to(ROOT))
Path(__file__).unlink()
